**packages/plugin-calendar/src/__tests__/calendar-bugfixes.test.tsx:56**
* This test file duplicates ResizeObserver/PointerEvent/offsetParent polyfills inline. The package already has shared setup files (e.g., `packages/plugin-calendar/test/setup.ts`), but `vitest.setup.ts` currently only imports jest-dom; consider moving these polyfills into the shared Vitest setup and removing the per-test duplication to reduce maintenance and drift.
```
// Mock ResizeObserver
class ResizeObserver {
  observe() {}
  unobserve() {}
  disconnect() {}
}
global.ResizeObserver = ResizeObserver;

// Mock PointerEvents for Radix
if (!global.PointerEvent) {
  class PointerEvent extends Event {
    button: number;
    ctrlKey: boolean;
    metaKey: boolean;
    shiftKey: boolean;
    constructor(type: string, props: any = {}) {
      super(type, props);
      this.button = props.button || 0;
      this.ctrlKey = props.ctrlKey || false;
      this.metaKey = props.metaKey || false;
      this.shiftKey = props.shiftKey || false;
    }
  }
  // @ts-expect-error Mocking global PointerEvent
  global.PointerEvent = PointerEvent as any;
}

// Mock HTMLElement.offsetParent for Radix Popper
Object.defineProperty(HTMLElement.prototype, 'offsetParent', {
  get() {
    return this.parentElement;
  },
});
```
**packages/plugin-calendar/src/CalendarView.tsx:576**
* MonthView event cards are rendered as a `<div role="button">` without keyboard support (e.g., `tabIndex=0` and Enter/Space handling) and without using a semantic `<button>`. Since this block was touched, consider switching to a real button (preferred) or adding the missing keyboard/focus behavior to make event clicks accessible.
```
                  <div
                    key={event.id}
                    role="button"
                    title={event.title}
                    aria-label={event.title}
                    draggable={!!onEventDrop}
```
